kiClientOptions | undefined\n  private clientFactory: AwikiClientFactory | undefined\n  private provider: RegisteredProvider | undefined\n  private runtimeGeneration = 0\n  private tenantSwitching = false\n  private readonly tenantParticipants = new Set<AwikiTenantLifecycleParticipant>()\n  private activeCapabilities: AwikiTenantCapabilities | undefined\n  private updatePolicyStatus: AwikiUpdatePolicyStatus | undefined\n  private updatePolicyRequest: AbortController | undefined\n  private updatePolicyTask: Promise<AwikiUpdatePolicyStatus> | undefined\n  private updatePolicyTaskKey: string | undefined\n  private desktopDistribution: AwikiDesktopDistributionService | undefined\n  private signedOut: boolean | undefined\n  private sessionMutation: Promise<void> = Promise.resolve()\n  private sessionRevision = 0\n  private activeIdentityDid: AwikiIdentity['did'] | undefined\n  private pendingDeviceJoin: PendingDeviceJoinContinuation | undefined\n  private activeDeviceJoinSessionId: string | undefined\n  private readonly requestRefs = new Map<string, string>()\n  private readonly requestSessions = new Map<string, string>()\n  private readonly deviceRefs = new Map<string, string>()\n  private readonly deviceIds = new Map<string, string>()\n  private readonly rootTransfers = new Map<string, PendingRootTransfer>()\n  private readonly activeSummaryRequests = new Set<AbortController>()\n  private summaryProvider: AwikiSummaryProvider | undefined\n  private readonly hostContext: Context\n  /** Trusted same-process external HTTP authentication dispatcher. Never Remote. */\n  readonly externalHttpAuth: AwikiExternalHttpAuth\n  private integrationClient: AwikiIntegrationClient | undefined\n  private mailListClient!: AwikiMailListClient\n  private workspaceContext: Context | undefined\n\n  /**\n   * @param ctx - owning Host context.\n   * @param config - service endpoints, SDK state path, and public limits.\n   */\n  constructor(ctx: Context, config: Config) {\n    super(ctx, 'awiki')\n    this.hostContext = ctx\n    this.resolved = resolveConfig(ctx, config)\n    this.externalHttpAuth = createAwikiExternalHttpAuth(() => this.acquireExternalHttpAuthSession())\n    this.startupUserServiceDomain = this.resolved.userServiceDomain\n    ctx.inject(['settings'], (settingsCtx) => {\n      const provider = settingsCtx.settings\n      const settingsScope = settingsCtx.settings.register(\n        AWIKI_SETTINGS_NAMESPACE,\n        AwikiSettingsSchema,\n        {\n          base: { domain: this.resolved.userServiceDomain },\n          applies: 'restart',\n          validate: validateAwikiSettings,\n        },\n      )\n      this.settingsProvider = provider\n      this.startupUserServiceDomain = settingsScope.get().domain\n      settingsCtx.effect(() => () => {\n        if (this.settingsProvider === provider) {\n          this.settingsProvider = undefined\n          this.startupUserServiceDomain = this.resolved.userServiceDomain\n        }\n      }, 'awiki: release settings namespace')\n    })\n    ctx.inject(['connection'], (connectionCtx) => {\n      registerAwikiSettingsTransport(\n        connectionCtx.connection,\n        createAwikiSettingsRpcHandler(\n          () => this.settingsProvider,\n          {\n            describe: () => this.getTenantRegistryView(),\n            create: (displayName, domain) => this.createCustomTenant(displayName, domain),\n            rename: (tenantId, displayName) => this.renameCustomTenant(tenantId, displayName),\n            switch: tenantId => this.switchTenant(tenantId),\n            archive: tenantId => this.archiveCustomTenant(tenantId),\n            describeUpdate: () => this.getUpdatePolicyStatus(),\n            refreshUpdate: () => this.refreshUpdatePolicy(),\n            describeDesktopUpdate: () => this.getDesktopUpdate(),\n            refreshDesktopUpdate: () => this.refreshDesktopUpdate(),\n          },\n        ),\n      )\n    })\n    ctx.inject(['workspaceRegistry'], (workspaceCtx) => {\n      this.w