erenceStore(options.stateRoot)\n    this.mailListClient = new AwikiMailListClient(options.mailServiceUrl, this.externalHttpAuth)\n    this.integrationClient = undefined\n    this.activeCapabilities = {\n      tenantId: tenant.tenantId,\n      generation: this.runtimeGeneration,\n      online: false,\n      handleRecoveryPhoneEnabled: false,\n    }\n    this.signedOut = undefined\n    this.activeIdentityDid = undefined\n    this.pendingDeviceJoin = undefined\n    this.activeDeviceJoinSessionId = undefined\n  }\n\n  private openTenantProvider(tenant: AwikiTenantProfile, factory: AwikiClientFactory, startRuntime = true): RegisteredProvider {\n    const options = this.optionsForTenant(tenant)\n    const client = factory(options)\n    const provider: RegisteredProvider = {\n      client,\n      realtimeGeneration: 0,\n      agentConsumerGeneration: 0,\n      localDeviceJoinRequestCountAfterSync: 0,\n    }\n    this.bindTenantState(tenant, options)\n    this.provider = provider\n    void this.refreshUpdatePolicy().catch(() => undefined)\n    if (startRuntime) this.ensureProviderRuntime(provider)\n    return provider\n  }\n\n  /** Read the Host-owned catalog for trusted loopback settings surfaces. */\n  getTenantRegistryView(): AwikiTenantRegistryView {\n    // The public generation fences runtime requests; the catalog keeps its own durable revision.\n    return { ...this.ensureTenantRegistry().snapshot(this.tenantSwitching), generation: this.runtimeGeneration }\n  }\n\n  /** Browser-safe, same-process update state for Desktop and loopback settings. */\n  getUpdatePolicyStatus(): AwikiUpdatePolicyStatus {\n    const tenant = this.activeTenant ?? this.ensureTenantRegistry().active()\n    const modelProxyVersion = this.currentModelProxyVersion()\n    return this.updatePolicyStatus ?? readAwikiUpdatePolicyStatus({\n      tenant, generation: this.runtimeGeneration, stateRoot: this.resolved.stateRoot,\n      currentPluginVersion: DSH_AWIKI_VERSION,\n      ...modelProxyVersion === undefined ? {} : { currentModelProxyVersion: modelProxyVersion },\n    })\n  }\n\n  /** Project only the active tenant's Desktop state; retain legacy detection without its fixed source. */\n  getDesktopUpdate(): AwikiDesktopDistribution | undefined {\n    const view = decodeDesktopDistribution(this.desktopDistribution?.getSnapshot())\n    if (view === undefined || view.schemaVersion === 1) return view\n    const tenant = this.activeTenant ?? this.ensureTenantRegistry().active()\n    if (this.tenantSwitching || view.tenantId !== tenant.tenantId\n      || view.policyOrigin !== new URL(tenant.backendBaseUrl).origin || view.tenantGeneration !== this.runtimeGeneration) {\n      return { schemaVersion: 2, distributionId: 'awiki-dsh-desktop', currentVersion: view.currentVersion,\n        channel: view.channel, state: 'unavailable', updateAvailable: false, usedCache: false }\n    }\n    return view\n  }\n\n  async refreshDesktopUpdate(): Promise<AwikiDesktopDistribution | undefined> {\n    const provider = this.desktopDistribution\n    if (provider === undefined) return undefined\n    await provider.check()\n    return this.getDesktopUpdate()\n  }\n\n  /** Refresh only the active generation; late results from old tenants are discarded. */\n  refreshUpdatePolicy(): Promise<AwikiUpdatePolicyStatus> {\n    const key = JSON.stringify([this.runtimeGeneration, this.currentModelProxyVersion()])\n    if (this.updatePolicyTask !== undefined && this.updatePolicyTaskKey === key) return this.updatePolicyTask\n    const task = this.performUpdatePolicyRefresh().finally(() => {\n      if (this.updatePolicyTask === task) this.updatePolicyTask = undefined\n    })\n    this.updatePolicyTask = task\n    this.updatePolicyTaskKey = key\n    return task\n  }\n\n  private async performUpdatePolicyRefresh(): Promise<AwikiUpdatePolicyStatus> {\n    const tenant = this.activeTenant ?? this.ensureTenantRegistry().active()\n    const generation = this.runtimeGeneration\n    this.updatePolicyRequest