      "path": "src/client/index.ts",
      "content": "/** AWiki browser plugin: one floating `shell.overlay` entry backed by Host Remote. */\n\nimport type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type { ConnectionHandle } from '@deepseek-ai/dsh-client-connection/client'\nimport awikiRemote from '@awiki/dsh-plugin/remote'\n// Type-only imports supply the generated `ctx.remote.awiki` and target slot.\nimport type {} from '@deepseek-ai/dsh-api-remotes/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-layout/client'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport { AWIKI_DOMAIN_FIELD, normalizeAwikiDomain } from '../domain.ts'\nimport { AWIKI_CLEAR_LOCAL_DATA_CONFIRMATION, AWIKI_LOGOUT_CONFIRMATION } from '../types.ts'\nimport type { AwikiIntegrationFields, AwikiIntegrationView } from '../types.ts'\nimport { AwikiClientBridge } from './awiki-client-bridge.ts'\nimport { AwikiController, type AwikiActionResult, type AwikiRemote } from './controller.ts'\nimport { AwikiOverlay } from './AwikiOverlay.tsx'\nimport { AwikiSettingsSection, type AwikiSettingsInjected } from './AwikiSettingsSection.tsx'\nimport {\n  clearIntegrationOperation,\n  clearIntegrationOperations,\n  durableIntegrationOperationId,\n  type IntegrationOperationKind,\n} from './integration-operation.ts'\nimport type { AwikiInjected } from './slots.ts'\nimport { createAwikiOverlayStore } from './store.ts'\nimport { en, zh } from './settings-locales.ts'\nimport { AwikiSettingsController } from './settings-controller.ts'\n\nexport type * from '../types.ts'\nexport type { AwikiActionResult, AwikiController, AwikiControllerStatus, AwikiRemote, AwikiSummaryStatus, AwikiSummaryView, AwikiView } from './controller.ts'\nexport type { AwikiClientBridge } from './awiki-client-bridge.ts'\nexport type { AwikiIdentityAccessProps } from './AwikiIdentityAccess.tsx'\nexport type { AwikiInjected, AwikiOverlayProps } from './slots.ts'\nexport type { AwikiSettingsInjected, AwikiSettingsSectionProps } from './AwikiSettingsSection.tsx'\nexport { createAwikiOverlayStore } from './store.ts'\n\nasync function durableIntegrationMutation<Value>(\n  kind: IntegrationOperationKind,\n  signature: string,\n  operation: (idempotencyKey: string) => Promise<AwikiActionResult<Value>>,\n): Promise<AwikiActionResult<Value>> {\n  const result = await operation(durableIntegrationOperationId(kind, signature))\n  if (result.ok) clearIntegrationOperation(kind)\n  return result\n}\n\n/** Required services: Remote, Connection transport, locale, and slot registry. */\nexport const inject = ['slots', 'remote', 'connection', 'locale']\n\n/**\n * Mount the optional AWiki Remote and register the frame-wide floating launcher and anchored chat panel.\n * @param ctx - browser context carrying slots and Remote.\n * @returns disposer for the slot injection and AWiki Remote contribution.\n */\nexport async function apply(ctx: ClientContext): Promise<() => Promise<void>> {\n  const disposeRemote = await ctx.remote.$mount(awikiRemote)\n  let disposeOverlay: (() => void) | undefined\n  let disposeSettings: (() => void) | undefined\n  let settingsController: AwikiSettingsController | undefined\n  let awikiController: AwikiController | undefined\n  try {\n    const remote = ctx.get('remote.awiki') as unknown as AwikiRemote | undefined\n    if (remote === undefined) throw new Error('ui-awiki: mounted Remote namespace is unavailable')\n    const connection = ctx.get('connection') as unknown as ConnectionHandle | undefined\n    if (connection === undefined) throw new Error('ui-awiki: Connection service is unavailable')\n    const settings = new AwikiSettingsController(connection)\n    settingsController = settings\n    const awiki = new AwikiController(remote)\n    awikiController = awiki\n    new AwikiClientBridge(ctx, awiki)\n    await settings.load()\n    ctx.effect(() => {\n      const disposeZh = ctx.locale.register('settings.awiki', 'zh', zh)\n      const disposeEn = ctx.locale.register('settings.awiki', 'en', en)\n      return () => { disposeEn(); disposeZh() }\n    }, 'ui-awiki: settings dictionaries')\n    disposeOverlay = ctx.slots.inject('shell.overlay', () => {\n      const dispose = ctx.slots.register({\n        name: 'shell.overlay',\n        id: 'awiki',\n        order: 20,\n        store: createAwikiOverlayStore,\n        inject: (): AwikiInjected => ({\n          drafts: awiki.drafts,\n          refreshIdentityAccess: () => awiki.refreshIdentityAccess(),\n          selectRecovery: id => awiki.selectRecovery(id),\n          leaveRecovery: () => awiki.leaveRecovery(),\n          continueRecoveryForHandle: handle => awiki.continueRecoveryForHandle(handle),\n          enterRecoveredSession: () => awiki.enterRecoveredSession(),\n          hooks: { awiki },\n          open: () => awiki.open(),\n          close: () => { awiki.close() },\n          inspectIdentityAccess: request => awiki.inspectIdentityAccess(request),\n          sendRegistrationOtp: request => awiki.sendRegistrationOtp(request),\n          registerIdentity: request => awiki.registerIdentity(request),\n          beginDeviceJoin: () => awiki.beginDeviceJoin(),\n          getDeviceJoinStatus: () => awiki.getDeviceJoinStatus(),\n          cancelDeviceJoin: () => awiki.cancelDeviceJoin(),\n          beginRecoveryFromDeviceJoin: request => awiki.beginRecoveryFromDeviceJoin(request),\n          retireDeviceIdentityForRejoin: () => awiki.retireDeviceIdentityForRejoin(),\n          refreshDeviceManagement: () => awiki.refreshDeviceManagement(),\n          getIdentityServices: () => awiki.getIdentityServices(),\n          updateIdentityServices: request => awiki.updateIdentityServices(request),\n          resumeIdentityServicesUpdate: request => awiki.resumeIdentityServicesUpdate(request),\n          startDeviceJoinVerification: request => awiki.startDeviceJoinVerification(request),\n          approveDeviceJoin: request => awiki.approveDeviceJoin(request),\n          rejectDeviceJoin: request => awiki.rejectDeviceJoin(request),\n          revokeDevice: request => awiki.revokeDevice(request),\n          retryDeviceManagement: request => awiki.retryDeviceManagement(request),\n          prepareRootTransfer: request => awiki.prepareRootTransfer(request),\n          confirmRootTransfer: request => awiki.confirmRootTransfer(request),\n          updateDisplayName: displayName => awiki.updateDisplayName(displayName),\n          updateProfile: request => awiki.updateProfile(request),\n          setAvatar: request => awiki.setAvatar(request),\n          clearAvatar: request => awiki.clearAvatar(request),\n          refreshAvatarProfile: () => awiki.refreshAvatarProfile(),\n          avatarDisplayProfiles: peers => awiki.avatarDisplayProfiles(peers),\n          avatarGroup: groupDid => awiki.avatarGroup(groupDid),\n          sendRecoveryOtp: request => awiki.sendRecoveryOtp(request),\n          prepareRecovery: request => awiki.prepareRecovery(request),\n          activateRecovery: () => awiki.activateRecovery(),\n          refreshRecoveryStatus: () => awiki.refreshRecoveryStatus(),\n          resumeRecovery: () => awiki.resumeRecovery(),\n          discardRecovery: () => awiki.discardRecovery(),\n          loadMoreConversations: () => awiki.loadMoreConversations(),\n          hideConversation: conversationId => awiki.hideConversation(conversationId),\n          restoreConversation: conversationId => awiki.restoreConversation(conversationId),\n          startDirectChat: handle => awiki.startDirectChat(handle),\n          createGroup: (name, members, encrypted, operationId) => awiki.createGroup(name, members, encrypted, operationId),\n          joinGroup: groupDid => awiki.joinGroup(groupDid),\n          repairSelectedGroupSecurity: () => awiki.repairSelectedGroupSecurity(),\n          refreshSelectedGroup: () => awiki.refreshSelectedGroup(),\n          loadMoreGroupMembers: () => awiki.loadMoreGroupMembers(),\n          addSelectedGroupMember: member => awiki.addSelectedGroupMember(member),\n          removeSelectedGroupMember: member => awiki.removeSelectedGroupMember(member),\n          leaveSelectedGroup: () => awiki.leaveSelectedGroup(),\n          selectConversation: conversationId => awiki.selectConversation(conversationId),\n          markSelectedConversationRead: () => awiki.markSelectedConversationRead(),\n          loadOlderHistory: () => awiki.loadOlderHistory(),\n          summarizeConversation: () => awiki.summarizeConversation(),\n          setSummaryCollapsed: (conversationId, collapsed) => { awiki.setSummaryCollapsed(conversationId, collapsed) },\n          retryMessageSecurity: () => awiki.retryMessageSecurity(),\n          setMessageSecurity: (id, encrypted) => awiki.setMessageSecurity(id, encrypted),\n          sendText: (text, clientMessageId, mentions, security) => awiki.sendText(text, clientMessageId, mentions, security),\n          sendAttachment: file => awiki.sendAttachment(file),\n          downloadAttachment: (messageId, attachmentId) => awiki.downloadAttachment(messageId, attachmentId),\n          logout: () => awiki.logout({ confirmation: AWIKI_LOGOUT_CONFIRMATION }),\n          login: () => awiki.login(),\n          clearLocalIdentity: async () => {\n            const result = await awiki.clearLocalData({ confirmation: AWIKI_CLEAR_LOCAL_DATA_CONFIRMATION })\n            return result.ok ? { ok: true, value: undefined } : result\n          },\n          getConfig: () => awiki.getConfig(),\n          getMailAccount: () => awiki.getMailAccount(),\n          listMailInbox: request => awiki.listMailInbox(request),\n          readMail: request => awiki.readMail(request),\n          markMailRead: request => awiki.markMailRead(request),\n          sendMail: request => awiki.sendMail(request),\n          downloadMailAttachment: request => awiki.downloadMailAttachment(request),\n        }),\n      }, AwikiOverlay)\n      return dispose\n    })\n    const injectedSettings = (): AwikiSettingsInjected => ({\n      hooks: { awikiTenants: settings.tenantScope, awikiSettings: settings, awiki },\n      saveDomain: async (raw) => {\n        const domain = normalizeAwikiDomain(raw)\n        await settings.set(AWIKI_DOMAIN_FIELD, domain)\n      },\n      resetDomain: () => settings.unset(AWIKI_DOMAIN_FIELD),\n      createTenant: (displayName, domain) => settings.createTenant(displayName, domain),\n      renameTenant: (tenantId, displayName) => settings.renameTenant(tenantId, displayName),\n      switchTenant: tenantId => awiki.switchTenant(() => settings.switchTenant(tenantId)),\n      archiveTenant: tenantId => settings.archiveTenant(tenantId),\n      refreshUpdatePolicy: () => settings.refreshUpdatePolicy(),\n      clearLocalData: async () => {\n        const result = await awiki.clearLocalData({ confirmation: AWIKI_CLEAR_LOCAL_DATA_CONFIRMATION })\n        if (!result.ok) throw new Error(result.error)\n      },\n      drafts: awiki.drafts,\n      loadAwiki: () => awiki.open(),\n      refreshDeviceManagement: () => awiki.refreshDeviceManagement(),\n          getIdentityServices: () => awiki.getIdentityServices(),\n          updateIdentityServices: request => awiki.updateIdentityServices(request),\n          resumeIdentityServicesUpdate: request => awiki.resumeIdentityServicesUpdate(request),\n      startDeviceJoinVerification: request => awiki.startDeviceJoinVerification(request),\n      approveDeviceJoin: request => awiki.approveDeviceJoin(request),\n      rejectDeviceJoin: request => awiki.rejectDeviceJoin(request),\n      revokeDevice: request => awiki.revokeDevice(request),\n      retryDeviceManagement: request => awiki.retryDeviceManagement(request),\n          prepareRootTransfer: request => awiki.prepareRootTransfer(request),\n      confirmRootTransfer: request => awiki.confirmRootTransfer(request),\n      loadIntegration: async () => {\n        const result = await awiki.getIntegration()\n        if (!result.ok && result.failureCode === 'not-found') {\n          clearIntegrationOperations()\n          return { ok: true, value: null }\n        }\n        if (result.ok) clearIntegrationOperations()\n        return result\n      },\n      saveIntegration: (fields: AwikiIntegrationFields, current: AwikiIntegrationView | null) => current === null\n        ? durableIntegrationMutation('create', JSON.stringify(fields), idempotencyKey => awiki.createIntegration({ ...fields, idempotencyKey }))\n        : durableIntegrationMutation(\n            'update',\n            JSON.stringify({ owner: current.owner.handle, revision: current.revision, fields }),\n            idempotencyKey => awiki.updateIntegration({ ...fields, expectedRevision: current.revision, idempotencyKey }),\n          ),\n      rotateIntegrationId: current => durableIntegrationMutation(\n        'rotate',\n        `${current.owner.handle}:${current.id}:${current.revision}`,\n        idempotencyKey => awiki.rotateIntegrationId({ expectedRevision: current.revision, idempotencyKey }),\n      ),\n      closeIntegration: current => durableIntegrationMutation(\n        'close',\n        `${current.owner.handle}:${current.id}:${current.revision}`,\n        idempotencyKey => awiki.closeIntegration({ expectedRevision: current.revision, idempotencyKey }),\n      ),\n      reopenIntegration: (fields, current) => durableIntegrationMutation(\n        'reopen',\n        JSON.stringify({ owner: current.owner.handle, revision: current.revision, fields }),\n        idempotencyKey => awiki.reopenIntegration({\n          ...fields,\n          expectedRevision: current.revision,\n          idempotencyKey,\n        }),\n      ),\n      listOwnedGroups: () => awiki.listOwnedGroups(),\n      openIntegrationGuide: () => { awiki.openIntegrationGuide() },\n    })\n    disposeSettings = ctx.slots.inject('settings.section', () => ctx.slots.register({\n      name: 'settings.section',\n      id: 'awiki',\n      order: 30,\n      label: () => ctx.locale.bind('settings.awiki')('nav'),\n      locale: 'settings.awiki',\n      inject: injectedSettings,\n    }, AwikiSettingsSection))\n  } catch (error) {\n    disposeSettings?.()\n    disposeOverlay?.()\n    awikiController?.dispose()\n    settingsController?.dispose()\n    await disposeRemote()\n    throw error\n  }\n  return async () => {\n    disposeSettings?.()\n    disposeOverlay?.()\n    awikiController?.dispose()\n    settingsController?.dispose()\n    await disposeRemote()\n  }\n}\n"
    },
    {
      "path": "tests/listener.spec.ts",
      "content": "import { lstat, mkdtemp, realpath, rm } from 'node:fs/promises'\nimport { tmpdir } from 'node:os'\nimport { join } from 'node:path'\nimport { afterEach, describe, expect, it } from 'vitest'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { Agent, AgentHandle } from '@deepseek-ai/dsh-agent'\nimport { SessionId, type SessionEvent } from '@deepseek-ai/dsh-session'\nimport type { Workspace } from '@deepseek-ai/dsh-workspace'\nimport {\n  AwikiAgentListener,\n  DshAwikiListenerAgentRuntime,\n  finalAssistantText,\n  type AwikiListenerAgentRuntime,\n  type AwikiListenerAgentSession,\n} from '../src/listener.ts'\nimport {\n  AwikiListenerStateStore,\n  type AwikiListenerConversationState,\n} from '../src/listener-state.ts'\nimport type {\n  AwikiSdkAgentInboxClient,\n  AwikiSdkListenerConversation,\n  AwikiSdkListenerMessage,\n} from '../src/provider-api.ts'\nimport type {\n  AwikiConversationId,\n  AwikiDid,\n  AwikiMessage,\n  AwikiMessageId,\n  AwikiSendTextRequest,\n} from '../src/types.ts'\n\nconst roots: string[] = []\n\nafterEach(async () => {\n  await Promise.all(roots.splice(0).map(root => rm(root, { recursive: true, force: true })))\n})\n\nconst conversation: Extract<AwikiSdkListenerConversation, { kind: 'direct' }> = {\n  kind: 'direct',\n  id: 'conversation-1',\n  peerDid: 'did:awiki:bob',\n  peerHandle: 'Bob@awiki.example',\n  unreadCount: 1,\n  lastMessageAt: 1,\n}\n\nfunction incoming(id: string, text: string, sentAt: number): AwikiSdkListenerMessage {\n  return {\n    id,\n    conversationId: conversation.id,\n    conversationKind: 'direct',\n    senderDid: conversation.peerDid,\n    sentAt,\n    outgoing: false,\n    content: { kind: 'text', text },\n  }\n}\n\nclass FakeAwiki implements AwikiSdkAgentInboxClient {\n  readonly sent: AwikiSendTextRequest[] = []\n  readonly marked: AwikiConversationId[] = []\n  readonly history: AwikiSdkListenerMessage[] = []\n  readonly operations: string[] = []\n  conversations: AwikiSdkListenerConversation[] = [conversation]\n  sendFailures = 0\n  historyFailures = 0\n\n  listConversations() {\n    this.operations.push('list')\n    return Promise.resolve({ items: this.conversations, hasMore: false })\n  }\n\n  getHistory(request: Parameters<AwikiSdkAgentInboxClient['getHistory']>[0]) {\n    this.operations.push('history')\n    if (this.historyFailures > 0) {\n      this.historyFailures -= 1\n      return Promise.reject(new Error('injected history failure'))\n    }\n    const limit = request.limit ?? 100\n    const end = request.cursor === undefined ? this.history.length : Number(request.cursor)\n    const start = Math.max(0, end - limit)\n    return Promise.resolve({\n      items: this.history.slice(start, end),\n      hasMore: start > 0,\n      ...(start > 0 ? { nextCursor: String(start) as never } : {}),\n    })\n  }\n\n  markConversationRead(conversationId: AwikiConversationId) {\n    this.marked.push(conversationId)\n    return Promise.resolve(1)\n  }\n\n  sendText(request: AwikiSendTextRequest): Promise<AwikiMessage> {\n    this.sent.push(request)\n    if (this.sendFailures > 0) {\n      this.sendFailures -= 1\n      return Promise.reject(new Error('injected send failure'))\n    }\n    return Promise.resolve({\n      id: `outgoing-${this.sent.length}` as AwikiMessageId,\n      conversationId: conversation.id as AwikiConversationId,\n      conversationKind: 'direct',\n      senderDid: 'did:awiki:listener' as AwikiDid,\n      sentAt: Date.now(),\n      outgoing: true,\n      content: { kind: 'text', text: request.text },\n    })\n  }\n\n  append(message: AwikiSdkListenerMessage): void {\n    this.history.push(message)\n    const unreadCount = this.history.filter(item => !item.outgoing).length\n    this.conversations = [{ ...conversation, unreadCount, lastMessageAt: message.sentAt }]\n  }\n}\n\nclass FakeAgents implements AwikiListenerAgentRuntime {\n  readonly opened: Array<string | undefined> = []\n  readonly prompts: string[] = []\n  readonly resets: Array<string | undefined> = []\n  disposed = 0\n  private next = 1\n\n  open(sessionId?: string): Promise<AwikiListenerAgentSession> {\n    this.opened.push(sessionId)\n    const resolved = sessionId ?? `session-${this.next++}`\n    return Promise.resolve({\n      sessionId: resolved,\n      prompt: (text) => {\n        this.prompts.push(text)\n        return Promise.resolve(`回复：${text}`)\n      },\n    })\n  }\n\n  reset(sessionId?: string): Promise<void> {\n    this.resets.push(sessionId)\n    return Promise.resolve()\n  }\n\n  dispose(): Promise<void> {\n    this.disposed += 1\n    return Promise.resolve()\n  }\n}\n\nasync function fixture(\n  allowedPeers: readonly string[] = ['bob@awiki.example'],\n  initialRoute?: AwikiListenerConversationState,\n) {\n  const root = await mkdtemp(join(tmpdir(), 'dsh-awiki-listener-'))\n  roots.push(root)\n  if (initialRoute !== undefined) {\n    const store = new AwikiListenerStateStore(root, 'did:awiki:owner')\n    await store.save({\n      version: 2,\n      identityScopeHash: store.identityScopeHash,\n      conversations: { [conversation.id]: initialRoute },\n    })\n  }\n  const awiki = new FakeAwiki()\n  const agents = new FakeAgents()\n  const listener = new AwikiAgentListener(awiki, agents, {\n    allowedPeers, identityScope: 'did:awiki:owner',\n    workspacePath: join(root, 'workspace'),\n    stateRoot: root,\n  })\n  return { root, awiki, agents, listener }\n}\n\ndescribe('AWiki Agent listener', () => {\n  it('creates and then continues one DSH session for an authorized Direct peer', async () => {\n    const f = await fixture()\n    f.awiki.append(incoming('message-1', '你好', 1))\n    await f.listener.reconcileOnce()\n    await f.listener.whenIdle()\n\n    expect(f.agents.opened).toEqual([undefined])\n    expect(f.agents.prompts).toEqual(['你好'])\n    expect(f.awiki.sent[0]).toMatchObject({\n      target: { kind: 'direct', conversationId: conversation.id },\n      text: '回复：你好',\n    })\n    expect(f.awiki.sent[0]?.idempotencyKey).toMatch(/^awiki-listener-[a-f0-9]{64}-0$/u)\n\n    f.awiki.append(incoming('message-2', '继续', 2))\n    await f.listener.reconcileOnce()\n    await f.listener.whenIdle()\n    expect(f.agents.opened).toEqual([undefined, 'session-1'])\n    expect(f.agents.prompts).toEqual(['你好', '继续'])\n    expect(f.awiki.marked).toEqual([conversation.id, conversation.id])\n    await f.listener.dispose()\n  })\n\n  it('inherits encryption across retries and keeps mixed messages in one session', async () => {\n    const f = await fixture()\n    f.awiki.append(incoming('plain-1', 'ordinary', 1))\n    await f.listener.reconcileOnce(); await f.listener.whenIdle()\n    f.awiki.sendFailures = 1\n    f.awiki.append({ ...incoming('secure-2', 'secret', 2), encrypted: true, decryptionState: 'decrypted' })\n    await f.listener.reconcileOnce(); await f.listener.whenIdle()\n    await f.listener.reconcileOnce(); await f.listener.whenIdle()\n    expect(f.awiki.sent[0]?.security).toBe('plain')\n    expect(f.awiki.sent.slice(1).every(item => item.security === 'e2ee-required')).toBe(true)\n    expect(f.awiki.sent[1]?.idempotencyKey).toBe(f.awiki.sent[2]?.idempotencyKey)\n    expect(f.agents.opened.slice(1).every(id => id === 'session-1')).toBe(true)\n    const prompts = [...f.agents.prompts]\n    f.awiki.append({ ...incoming('opaque-3', 'ciphertext-must-not-reach-model', 3), encrypted: true, decryptionState: 'failed' })\n    await f.listener.reconcileOnce(); await f.listener.whenIdle()\n    expect(f.agents.prompts).toEqual(prompts)\n    await f.listener.dispose()\n  })\n\n  it('resumes the persisted route after restart without replaying the watermark', async () => {\n    const f = await fixture()\n    f.awiki.append(incoming('message-1', '第一条', 1))\n    await f.listener.reconcileOnce()\n    await f.listener.whenIdle()\n    await f.listener.dispose()\n\n    f.awiki.append(incoming('message-2', '第二条', 2))\n    const nextAgents = new FakeAgents()\n    const restarted = new AwikiAgentListener(f.awiki, nextAgents, {\n      allowedPeers: ['did:awiki:bob'], identityScope: 'did:awiki:owner', workspacePath: join(f.root, 'workspace'), stateRoot: f.root,\n    })\n    await restarted.reconcileOnce()\n    await restarted.whenIdle()\n\n    expect(nextAgents.opened).toEqual(['session-1'])\n    expect(nextAgents.prompts).toEqual(['第二条'])\n    await expect(new AwikiListenerStateStore(f.root, 'did:awiki:owner').load()).resolves.toMatchObject({\n      conversations: {\n        'conversation-1': {\n          peerDid: 'did:awiki:bob', sessionId: 'session-1', lastProcessedMessageId: 'message-2',\n        },\n      },\n    })\n    await restarted.dispose()\n  })\n\n  it('does not replay bounded history when a missing watermark has no unread successor', async () => {\n    const root = await mkdtemp(join(tmpdir(), 'dsh-awiki-listener-'))\n    roots.push(root)\n    const store = new AwikiListenerStateStore(root, 'did:awiki:owner')\n    await store.save({\n      version: 2,\n      identityScopeHash: store.identityScopeHash,\n      conversations: {\n        [conversation.id]: {\n          peerDid: conversation.peerDid,\n          sessionId: 'session-existing',\n          lastProcessedMessageId: 'message-outside-window',\n        },\n      },\n    })\n    const awiki = new FakeAwiki()\n    awiki.history.push(incoming('message-old', '不得重放', 1))\n    awiki.conversations = [{ ...conversation, unreadCount: 0 }]\n    const agents = new FakeAgents()\n    const listener = new AwikiAgentListener(awiki, agents, {\n      allowedPeers: [conversation.peerDid], identityScope: 'did:awiki:owner',\n      workspacePath: join(root, 'workspace'),\n      stateRoot: root,\n    })\n\n    await listener.reconcileOnce()\n    await listener.whenIdle()\n\n    expect(agents.opened).toEqual([])\n    expect(agents.prompts).toEqual([])\n    expect(awiki.sent).toEqual([])\n    await listener.dispose()\n  })\n\n  it('fails closed when more than 2,000 newer messages leave the persisted watermark outside the scan window', async () => {\n    const f = await fixture(['did:awiki:bob'], {\n      peerDid: conversation.peerDid,\n      sessionId: 'session-existing',\n      lastProcessedMessageId: 'message-watermark',\n    })\n    f.awiki.history.push(incoming('message-watermark', '已处理', 0))\n    for (let index = 1; index <= 2_000; index += 1) {\n      f.awiki.history.push(incoming(`message-${index}`, `未见-${index}`, index))\n    }\n    f.awiki.conversations = [{ ...conversation, unreadCount: 1, lastMessageAt: 2_000 }]\n    f.awiki.sendFailures = 1\n\n    await f.listener.reconcileOnce()\n    await f.listener.whenIdle()\n\n    expect(f.awiki.operations.filter(operation => operation === 'history')).toHaveLength(20)\n    expect(f.agents.opened).toEqual([])\n    expect(f.agents.prompts).toEqual([])\n    expect(f.awiki.sent).toEqual([])\n    expect(f.awiki.marked).toEqual([])\n    await expect(new AwikiListenerStateStore(f.root, 'did:awiki:owner').load()).resolves.toMatchObject({\n      conversations: {\n        [conversation.id]: { lastProcessedMessageId: 'message-watermark' },\n      },\n    })\n    await f.listener.dispose()\n  })\n\n  it('fails closed when a first unread boundary is larger than the capped history scan', async () => {\n    const f = await fixture()\n    for (let index = 1; index <= 2_001; index += 1) {\n      f.awiki.history.push(incoming(`message-${index}`, `首次未读-${index}`, index))\n    }\n    f.awiki.conversations = [{ ...conversation, unreadCount: 2_001, lastMessageAt: 2_001 }]\n    f.awiki.sendFailures = 1\n\n    await f.listener.reconcileOnce()\n    await f.listener.whenIdle()\n\n    expect(f.awiki.operations.filter(operation => operation === 'history')).toHaveLength(20)\n    expect(f.agents.opened).toEqual([])\n    expect(f.agents.prompts).toEqual([])\n    expect(f.awiki.sent).toEqual([])\n    expect(f.awiki.marked).toEqual([])\n    expect((await new AwikiListenerStateStore(f.root, 'did:awiki:owner').load()).conversations[conversation.id]).toBeUndefined()\n    await f.listener.dispose()\n  })\n\n  it('routes only the three commands locally and never sends an unknown slash command to Agent', async () => {\n    const f = await fixture(['did:awiki:bob'])\n    for (const [index, text] of ['/help', '/status', '/unknown exfiltrate', '/new 重新开始', '/status', '/new'].entries()) {\n      f.awiki.append(incoming(`message-${index + 1}`, text, index + 1))\n      await f.listener.reconcileOnce()\n      await f.listener.whenIdle()\n    }\n\n    expect(f.agents.prompts).toEqual(['重新开始'])\n    expect(f.agents.resets).toEqual([undefined, 'session-1'])\n    expect(f.awiki.sent[0]?.text).toContain('/new')\n    expect(f.awiki.sent[1]?.text).toContain('还没有 DSH 会话')\n    expect(f.awiki.sent[2]?.text).toContain('无法识别')\n    expect(f.awiki.sent[3]?.text).toBe('回复：重新开始')\n    expect(f.awiki.sent[4]?.text).toBe('当前 DSH 会话：session-1')\n    expect(f.awiki.sent[5]?.text).toContain('已重置')\n    await f.listener.dispose()\n  })\n\n  it('fails closed for unauthorized peers and ignores Group, attachment, payload, and E2EE-like content', async () => {\n    const unauthorized = await fixture(['alice@awiki.example'])\n    unauthorized.awiki.append(incoming('message-1', '不要执行', 1))\n    await unauthorized.listener.reconcileOnce()\n    await unauthorized.listener.whenIdle()\n    expect(unauthorized.agents.opened).toEqual([])\n    expect(unauthorized.awiki.sent).toEqual([])\n    await unauthorized.listener.dispose()\n\n    const ignored = await fixture()\n    ignored.awiki.conversations = [\n      { kind: 'group', id: 'group-1', unreadCount: 1, lastMessageAt: 1 },\n      conversation,\n    ]\n    ignored.awiki.append({ ...incoming('message-2', 'opaque', 2), content: { kind: 'ignored' } })\n    await ignored.listener.reconcileOnce()\n    await ignored.listener.whenIdle()\n    expect(ignored.agents.opened).toEqual([])\n    expect(ignored.awiki.sent).toEqual([])\n    await expect(new AwikiListenerStateStore(ignored.root, 'did:awiki:owner').load()).resolves.to